import React, { useState } from "react";
import { withRouter, useHistory, useLocation } from "react-router-dom";
import logo from "../../assets/logo.png";
import logo_2 from "../../assets/logo2.png";
import "antd/dist/antd.css";
import { Row, Col, Form, Dropdown, Input, Button, Checkbox, Menu } from "antd";
import "./styles.css";
import { login, loadUser } from "../../redux/Thunk/auth";
import { connect } from "react-redux";

const emailPattern = /^\w+([\.-]?\w+)*@\w+([\.-]?\w+)*(\.\w{2,3})+$/;

function Login(props) {
  const [formData, setFormData] = useState({
    email: "",
    emailIsValid: false,
    emailHelp: "",
    emailValidateStatus: "",

    password: "",
    passwordIsValid: false,
    passwordHelp: "",
    passwordValidateStatus: "",

    // role: "1",
    // roleIsValid: false,
    // roleHelp: "",
    // roleValidateStatus: "",
    // remember: false,
    // firstTime: 0,
  });

  const onChangeValidator = (name, value) => {
    switch (name) {
      case "email":
        if (!emailPattern.test(value)) {
          setFormData({
            ...formData,
            [name]: value,
            emailValidateStatus: "error",
            emailHelp: "Enter a valid Email address!",
            emailIsValid: false,
          });
        } else {
          setFormData({
            ...formData,
            [name]: value,
            emailValidateStatus: "success",
            emailHelp: "",
            emailIsValid: true,
          });
        }
        break;
      case "password":
        if (value.trim() === "" || value.length < 6) {
          setFormData({
            ...formData,
            [name]: value,
            passwordValidateStatus: "error",
            passwordHelp: "Enter more than 8 digit password!",
            passwordIsValid: false,
          });
        } else {
          setFormData({
            ...formData,
            [name]: value,
            passwordValidateStatus: "success",
            passwordHelp: "",
            passwordIsValid: true,
          });
        }
        break;
    }
  };

  const handleChange = e => {
    if (e.target.name === "email" || e.target.name === "password") {
      onChangeValidator(e.target.name, e.target.value);
    }
  };

  // function onRemember(e) {
  //   setFormData({ ...formData, [e.target.name]: e.target.checked });
  //   console.log(`checked = ${e.target.checked}`);
  // }

  // const menu = (
  //   <Menu onClick={handleMenuClick}>
  //     <Menu.Item key="2" value="manager">
  //       Manager
  //     </Menu.Item>
  //     <Menu.Item key="3" value="admin">
  //       Admin
  //     </Menu.Item>
  //   </Menu>
  // );

  // function handleMenuClick(e) {
  //   if (e.key === "1") {
  //     setFormData({
  //       ...formData,
  //       role: e.key,
  //       roleValidateStatus: "error",
  //       roleHelp: "Please select a role!",
  //       roleIsValid: false,
  //     });
  //   } else {
  //     setFormData({
  //       ...formData,
  //       role: e.key === "2" ? "manager" : "admin",
  //       roleValidateStatus: "success",
  //       roleHelp: "",
  //       roleIsValid: true,
  //     });
  //   }
  // }

  const handleSubmit = e => {
    const { email, password } = formData;
    // const { email, password, role, remember } = formData;

    e.preventDefault();

    let isFormValid = true;
    if (!formData.emailIsValid) {
      isFormValid = false;
      setFormData({
        emailValidateStatus: "error",
        emailHelp: "Enter your Email !",
      });
    }

    if (!formData.passwordIsValid) {
      isFormValid = false;
      setFormData({
        passwordIsValid: false,
        passwordHelp: "Enter your password !",
        passwordValidateStatus: "error",
      });
    }

    if (isFormValid) {
      props.loginUser({ email, password });
    } else {
      console.log("Validation Error");
    }
  };

  let history = useHistory();
  let location = useLocation();

  const { email, password } = formData;
  let { from } = location.state || { from: { pathname: "/" } };

  return (
    <div>
      {console.log("USER STATE", props.UserState)}
      <Row className="container-bx">
        <Col className="logo-Container" span={12}>
          <img className="img" src={logo} />{" "}
        </Col>
        <Col className="Login-Container" span={12}>
          <Form onSubmit={handleSubmit} className="login-form">
            <img className="form-img" src={logo_2} width="100%" />

            <Form.Item
              validateStatus={formData.emailValidateStatus}
              help={formData.emailHelp}
            >
              <Input
                type="email"
                name="email"
                value={email}
                onChange={handleChange}
                placeholder="Email"
                className="inputStyle"
                // prefix={
                //   <Icon
                //     type="mail"
                //     style={{
                //       color: "white",
                //       fontWeight: "bold",
                //       textIndent: "10px",
                //       fontSize: "15px"
                //     }}
                //   />
                // }
              />
            </Form.Item>

            <Form.Item
              validateStatus={formData.passwordValidateStatus}
              help={formData.passwordHelp}
            >
              <Input.Password
                placeholder="Password"
                name="password"
                className="inputStyle"
                value={password}
                onChange={e => handleChange(e)}
                // prefix={

                // <Icon
                //   type="lock"
                //   style={{
                //     color: "white",
                //     fontWeight: "bold",
                //     textIndent: "10px",
                //     fontSize: "15px"
                //   }}
                // />

                // }
              />
            </Form.Item>

            <Button
              onClick={handleSubmit}
              id="login-btn"
              disabled={!formData.emailIsValid || !formData.passwordIsValid}
            >
              Login
            </Button>
          </Form>
        </Col>
      </Row>
    </div>
  );
}

const mapDispatchToProps = (Dispatch, props) => ({
  loginUser: state => Dispatch(login(state, props)),
});

const mapStateToProps = state => ({
  UserState: state.userReducer,
});

export default connect(mapStateToProps, mapDispatchToProps)(withRouter(Login));
