import * as Action from "../actions/userActions/userActions";
import API from "../api/index";

const savetoken = token => {
  localStorage.setItem("auth_token", token);
};

const rememberUser = (id, fname, lname, email) => {
  localStorage.setItem("uId", id);
};

const loadUser = () => dispatch => {
  const token = localStorage.getItem("auth_token");
  if (token)
    API.get("/user/signIn", null, token, dispatch, (err, res) => {
      if (!err) {
        dispatch(Action.AddUser(res.user));
      }
    });
};

const login = (data, props) => dispatch => {
  API.post("/user/signIn", data, null, dispatch, (err, res) => {
    if (!err) {
      dispatch(Action.AddUser(res.user));
      savetoken(res.token);
      props.history.push("dashboard");
    } else {
      dispatch(Action.AddErr(err.errors));
      setTimeout(() => {
        dispatch(Action.AddErr([]));
      }, 1000);
      console.log(err);
    }
  });
};

const deleteUser = props => dispatch => {
  localStorage.removeItem("auth_token");
  dispatch(Action.DeleteUser());
  props.history.push("/login");
};

export { loadUser, login, deleteUser };
